import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const STATIC_FILES = new Map(Object.entries({"/index.html":"","/app.js":"","/manifest.webmanifest":"","/style.css":"","/service-worker.js":"","/icons/icon.svg":"","/icons/icon-512.png":"","/icons/icon-192.png":""}).map(([name, data]) => [name, Buffer.from(data, 'base64')]));
const PORT = Number(process.env.PORT) || 3000;
const SOURCE_URL = process.env.FUEL_SOURCE_URL || 'https://bensinpriser.nu/karta/data';
const SOURCE_NAME = 'Bensinpriser.nu';
const FALLBACK_BASE = process.env.FUEL_FALLBACK_BASE || 'https://pumperly.com';
const FRESH_MS = 15 * 60 * 1000;
const MAX_STALE_MS = 2 * 60 * 60 * 1000;
const MAX_BYTES = 12 * 1024 * 1024;
const MAX_STATIONS = 12000;

const state = { stations: [], fetchedAt: null, lastError: null, lastAttemptAt: 0, pending: null, sourceFormat: null, sourceUsed: SOURCE_NAME, sourceLink: 'https://bensinpriser.nu' };
const fuelFields = {
  '95': 'price95', '98': 'price98', diesel: 'priceDiesel',
  e85: 'priceEtanol', hvo100: 'priceBiodiesel', fordonsgas: 'priceFordonsgas',
};

// En del publika kartflöden levererar en lista direkt, andra omsluter den
// i exempelvis {stations:[...]} eller {data:{stations:[...]}}.
const stationContainerKeys = ['stations', 'data', 'results', 'markers', 'items', 'features', 'locations', 'records', 'rows', 'bensinstationer'];
function sourceShape(value) {
  if (Array.isArray(value)) return { type: 'array', count: value.length, sampleFields: Object.keys(value[0] || {}).slice(0, 30) };
  if (!value || typeof value !== 'object') return { type: typeof value };
  const keys = Object.keys(value);
  const arrays = keys.filter(key => Array.isArray(value[key])).map(key => ({ field: key, count: value[key].length }));
  return { type: 'object', fields: keys.slice(0, 30), arrays };
}
function extractStations(raw, depth = 0) {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== 'object' || depth > 3) return null;
  for (const key of stationContainerKeys) {
    if (!(key in raw)) continue;
    const result = extractStations(raw[key], depth + 1);
    if (result) return result;
  }
  // Ytterligare inkapsling (utan att utgå från ett visst fältnamn).
  for (const value of Object.values(raw)) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      const result = extractStations(value, depth + 1);
      if (result) return result;
    }
  }
  return null;
}
function parseCoordinate(value) {
  if (typeof value === 'string') value = value.replace(',', '.');
  return Number(value);
}
export function normalizeStations(raw) {
  const records = extractStations(raw);
  if (!records) throw new Error('Datakällan svarade inte med en stationslista. Format: ' + JSON.stringify(sourceShape(raw)));
  if (records.length > MAX_STATIONS) throw new Error('Stationslistan var oväntat stor.');
  const ids = new Set();
  return records.flatMap((source, index) => {
    if (!source || typeof source !== 'object' || Array.isArray(source)) return [];
    const item = source.properties && typeof source.properties === 'object' ? { ...source.properties, ...source } : source;
    const coords = source.geometry?.coordinates;
    const geo = source.position ?? source.location ?? source.coordinates ?? {};
    const lat = parseCoordinate(item.lat ?? item.latitude ?? item.latitud ?? geo.lat ?? geo.latitude ?? (Array.isArray(coords) ? coords[1] : undefined));
    const lng = parseCoordinate(item.lng ?? item.lon ?? item.long ?? item.longitude ?? item.longitud ?? geo.lng ?? geo.lon ?? geo.longitude ?? (Array.isArray(coords) ? coords[0] : undefined));
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || lat < 55.1 || lat > 69.2 || lng < 10.7 || lng > 24.4) return [];
    const id = String(item.id ?? source.id ?? `s-${index}`);
    if (ids.has(id)) return [];
    ids.add(id);
    const prices = {};
    for (const [fuel, field] of Object.entries(fuelFields)) {
      const value = item[field] ?? item.prices?.[field] ?? item.prices?.[fuel];
      // Saknade priser ska aldrig räknas som noll eller låtsaspriser.
      if (value === null || value === undefined || value === '') continue;
      const price = Number(typeof value === 'string' ? value.replace(',', '.') : value);
      const upper = fuel === 'fordonsgas' ? 70 : 50;
      if (Number.isFinite(price) && price >= 5 && price <= upper) prices[fuel] = price;
    }
    const short = value => String(value ?? '').trim().slice(0, 130);
    const brand = short(item.company ?? item.brand ?? item.chain) || 'Fristående';
    const city = short(item.commune ?? item.city ?? item.town);
    const county = short(item.county ?? item.region);
    const address = short(item.address ?? item.street);
    let sourceUrl = 'https://bensinpriser.nu/karta';
    if (typeof item.link === 'string' && item.link.length < 500) {
      try {
        const candidate = new URL(item.link, 'https://bensinpriser.nu');
        if (candidate.protocol === 'https:' && ['bensinpriser.nu', 'www.bensinpriser.nu'].includes(candidate.hostname)) sourceUrl = candidate.href;
      } catch { /* invalid link: use source homepage */ }
    }
    return [{ id, brand, city, county, address, lat, lng, prices, sourceUrl }];
  });
}

async function readSource() {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch(SOURCE_URL, {
      headers: { 'Accept': 'application/json', 'User-Agent': 'Tankkollen/1.0 (personal fuel-price viewer)' },
      signal: controller.signal,
      redirect: 'follow',
    });
    if (!response.ok) throw new Error(`Datakällan svarade med HTTP ${response.status}.`);
    const declaredLength = Number(response.headers.get('content-length'));
    if (declaredLength > MAX_BYTES) throw new Error('Datakällans svar är för stort.');
    if (!response.body) throw new Error('Tomt svar från datakällan.');
    const chunks = [];
    let size = 0;
    for await (const chunk of response.body) {
      size += chunk.length;
      if (size > MAX_BYTES) throw new Error('Datakällans svar överskred storleksgränsen.');
      chunks.push(chunk);
    }
    const json = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    state.sourceFormat = sourceShape(json);
    const stations = normalizeStations(json);
    if (!stations.some(s => Object.keys(s.prices).length > 0)) throw new Error('Primärkällan levererade inga användbara priser.');
    return stations;
  } finally { clearTimeout(timeout); }
}

// Reservkälla: Pumperlys dokumenterade, publika GeoJSON-API för aktuella stationspriser.
// Pumperly uppger att svenska prisuppgifter i sin tur kommer från Bensinpriser.nu.
// Varje drivmedel hämtas separat eftersom deras API accepterar en bränslekod/anrop.
const fallbackFuels = Object.freeze({ '95': 'E5', diesel: 'B7', '98': 'E5_98', hvo100: 'HVO', fordonsgas: 'CNG' });
export function normalizePumperly(rawByFuel) {
  const map = new Map();
  for (const [fuel, raw] of Object.entries(rawByFuel)) {
    if (!raw || raw.type !== 'FeatureCollection' || !Array.isArray(raw.features)) continue;
    if (raw.features.length > MAX_STATIONS) continue;
    for (const feature of raw.features) {
      if (!feature || feature.type !== 'Feature') continue;
      const props = feature.properties || {};
      if (props.country !== 'SE' || props.currency !== 'SEK') continue;
      const [lng, lat] = feature.geometry?.coordinates || [];
      if (!Number.isFinite(lat) || !Number.isFinite(lng) || lat < 55.1 || lat > 69.2 || lng < 10.7 || lng > 24.4) continue;
      const price = Number(props.price);
      const max = fuel === 'fordonsgas' ? 70 : 50;
      if (!Number.isFinite(price) || price < 5 || price > max) continue;
      const id = String(props.externalId || props.id || `${lat},${lng}`);
      const key = `${id}:${lat.toFixed(5)}:${lng.toFixed(5)}`;
      if (!map.has(key)) map.set(key, {
        id: 'p-' + key, brand: String(props.brand || props.name || 'Fristående').slice(0,130),
        address: String(props.address || '').slice(0,130), city: String(props.city || '').slice(0,130),
        county: '', lat, lng, prices: {}, sourceUrl: FALLBACK_BASE,
      });
      map.get(key).prices[fuel] = price;
    }
  }
  return [...map.values()];
}
async function readFallback() {
  const raw = {};
  const errors = [];
  await Promise.all(Object.entries(fallbackFuels).map(async ([fuel, code]) => {
    const url = new URL('/api/stations', FALLBACK_BASE);
    url.searchParams.set('bbox', '10.7,55.1,24.4,69.2');
    url.searchParams.set('fuel', code);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    try {
      const response = await fetch(url, { headers: { 'Accept': 'application/json', 'User-Agent': 'Tankkollen/1.1 (fuel-price viewer)' }, signal: controller.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const length = Number(response.headers.get('content-length') || 0);
      if (length > MAX_BYTES) throw new Error('För stort svar');
      const buffer = Buffer.from(await response.arrayBuffer());
      if (buffer.length > MAX_BYTES) throw new Error('För stort svar');
      const body = JSON.parse(buffer.toString('utf8'));
      if (body.type !== 'FeatureCollection' || !Array.isArray(body.features)) throw new Error('Inga GeoJSON-stationer');
      raw[fuel] = body;
    } catch (err) { errors.push(`${fuel}: ${err.message}`); }
    finally { clearTimeout(timeout); }
  }));
  const stations = normalizePumperly(raw);
  // Om reservkällan också är trasig ska vi visa ett fel, inte låtsas att data är aktuell.
  if (!stations.length) throw new Error('Reservkällan gav inga priser. ' + errors.join('; ').slice(0,400));
  return stations;
}

async function getStations(force = false) {
  if (state.pending) await state.pending;
  const age = state.fetchedAt ? Date.now() - Date.parse(state.fetchedAt) : Infinity;
  if (!force && age < FRESH_MS) return state;
  // Även manuell uppdatering begränsas för att inte överbelasta priskällan.
  if (force && age < 60 * 1000) return state;
  // Efter fel: undvik att varje besökare gör ett nytt anrop till källan.
  if (state.lastError && Date.now() - state.lastAttemptAt < 3 * 60 * 1000) return state;
  if (Date.now() - state.lastAttemptAt < 60 * 1000) return state;
  state.lastAttemptAt = Date.now();
  state.pending = (async () => {
    try {
      let stations;
      let primaryError = null;
      try {
        stations = await readSource();
        state.sourceUsed = SOURCE_NAME;
        state.sourceLink = 'https://bensinpriser.nu';
      } catch (error) {
        primaryError = error instanceof Error ? error.message : String(error);
        console.warn(`[källa] Primärkälla fel: ${primaryError}. Provar reservkälla.`);
        stations = await readFallback();
        state.sourceUsed = 'Pumperly / Bensinpriser.nu';
        state.sourceLink = FALLBACK_BASE;
      }
      state.stations = stations;
      state.fetchedAt = new Date().toISOString();
      state.lastError = null;
      console.log(`[källa] ${stations.length} prisstationer från ${state.sourceUsed}, hämtade ${state.fetchedAt}`);
    } catch (error) {
      state.lastError = error instanceof Error ? error.message : String(error);
      console.error(`[källa] ${state.lastError}`);
    }
  })();
  try { await state.pending; } finally { state.pending = null; }
  return state;
}


// Stationsregistret är OpenStreetMap-data och INTE en priskälla.
// Hämta endast den aktuella orten eller kartans synliga område och cacha i 48 timmar.
const CATALOG_TTL = 48 * 60 * 60 * 1000;
const catalogCache = new Map();
const catalogPending = new Map();
let catalogLastCall = 0;
const osmEndpoints = (process.env.OVERPASS_API_URL ? [process.env.OVERPASS_API_URL] : [
  'https://overpass.private.coffee/api/interpreter',
  'https://overpass-api.de/api/interpreter',
]);
const knownCenters = new Map(Object.entries({
  'köping':[59.512,15.996], 'västerås':[59.610,16.545], 'arboga':[59.394,15.838],
  'eskilstuna':[59.371,16.507], 'stockholm':[59.330,18.064], 'göteborg':[57.708,11.974],
  'malmö':[55.606,13.002], 'uppsala':[59.859,17.638], 'örebro':[59.274,15.213],
  'norrköping':[58.587,16.192], 'linköping':[58.410,15.622], 'jönköping':[57.781,14.156],
  'luleå':[65.584,22.155], 'umeå':[63.826,20.263], 'helsingborg':[56.048,12.695],
  'karlstad':[59.379,13.503], 'borås':[57.722,12.940], 'falun':[60.604,15.636],
}));
const folded = value => String(value || '').trim().toLocaleLowerCase('sv-SE');
const validSE = (lat,lng) => Number.isFinite(lat) && Number.isFinite(lng) && lat >= 55.1 && lat <= 69.2 && lng >= 10.7 && lng <= 24.4;

async function cityCenter(city) {
  const key = folded(city);
  if (knownCenters.has(key)) return knownCenters.get(key);
  const known = state.stations.filter(s => folded(s.city) === key && validSE(s.lat,s.lng));
  if (known.length) return [known.reduce((n,s) => n+s.lat,0)/known.length,known.reduce((n,s) => n+s.lng,0)/known.length];
  const url = new URL('https://photon.komoot.io/api/');
  url.searchParams.set('q', city+', Sverige'); url.searchParams.set('limit','15');
  const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), 7000);
  try {
    const r = await fetch(url, {signal:controller.signal, headers:{'Accept':'application/json'}});
    if (!r.ok) return null;
    const result = await r.json();
    const match = (result.features||[]).find(f => {
      const p=f.properties||{};
      return String(p.countrycode||'').toUpperCase()==='SE' &&
        folded(p.name)===key && ['city','town','village','hamlet','municipality'].includes(p.osm_value);
    });
    if (!match) return null;
    const [lng,lat] = match.geometry?.coordinates || [];
    return validSE(lat,lng) ? [lat,lng] : null;
  } catch {return null;} finally {clearTimeout(timer);}
}
function parseOSM(data) {
  if (!Array.isArray(data?.elements)) throw new Error('Ogiltigt svar från stationsregistret');
  const ids=new Set(); const output=[];
  for (const el of data.elements) {
    const t=el.tags||{}; const lat=el.lat??el.center?.lat; const lng=el.lon??el.center?.lon;
    if (!validSE(lat,lng)|| !['node','way','relation'].includes(el.type)) continue;
    const id=el.type+'/'+el.id;
    if (ids.has(id)) continue;
    ids.add(id);
    const brand=String(t.brand||t.operator||t.name||'Fristående mack').trim().slice(0,90);
    const addr=[t['addr:street'],t['addr:housenumber']].filter(Boolean).join(' ');
    const address=String(addr||t['addr:full']||t['addr:place']||'').slice(0,120);
    const city=String(t['addr:city']||t['addr:municipality']||'').slice(0,100);
    output.push({id:'osm-'+id,brand,address,city,lat,lng,sourceUrl:'https://www.openstreetmap.org/'+id});
    if (output.length>=1600)break;
  }
  return output;
}
async function overpass(query) {
  const errors=[];
  for (const endpoint of osmEndpoints) {
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),18000);
    try {
      const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','Accept':'application/json','User-Agent':'Tankkollen/5.0 (OSM stations, cached 48h)'},body:new URLSearchParams({data:query}).toString(),signal:controller.signal});
      if(!response.ok) throw new Error('HTTP '+response.status);
      const len=Number(response.headers.get('content-length')||0);
      if(len>4*1024*1024) throw new Error('För stort stationssvar');
      const buf=Buffer.from(await response.arrayBuffer());
      if(buf.length>4*1024*1024)throw new Error('För stort stationssvar');
      return parseOSM(JSON.parse(buf.toString('utf8')));
    } catch(e){errors.push(e?.message||String(e));} finally{clearTimeout(timer);}
  }
  throw new Error('OpenStreetMap-förfrågan misslyckades: '+errors.join('; ').slice(0,160));
}
async function catalogFor(key,query) {
  const hit=catalogCache.get(key);
  if(hit && Date.now()-hit.at<CATALOG_TTL) return {...hit,stale:false};
  if(catalogPending.has(key)) return catalogPending.get(key);
  if (catalogLastCall && Date.now()-catalogLastCall < 1100 && !hit) throw new Error('Stationsregistret är upptaget. Prova igen.');
  catalogLastCall=Date.now();
  const pending=(async()=>{
    try {
      const stations=await overpass(query);
      const value={at:Date.now(),stations,source:'OpenStreetMap'};
      if(catalogCache.size>150){ const oldest=catalogCache.keys().next().value;catalogCache.delete(oldest); }
      catalogCache.set(key,value);
      return {...value,stale:false};
    } catch(e){if(hit)return {...hit,stale:true};throw e;}
    finally{catalogPending.delete(key);}
  })();catalogPending.set(key,pending);return pending;
}
async function stationsInCity(city) {
  // Ortsregistret är oberoende av prisflödet och ska aldrig invänta dess timeout.
  const center=await cityCenter(city);
  if(!center) throw new Error('Ortens position kunde inte hittas');
  // Ca 8 km från ortcentrum – täcker även stationer strax utanför tätorten.
  const query=`[out:json][timeout:25];nwr["amenity"="fuel"](around:8000,${center[0].toFixed(5)},${center[1].toFixed(5)});out center tags;`;
  const data=await catalogFor('city:'+folded(city),query);
  return {...data,city,center,radiusKm:8};
}
async function stationsInMapBox(raw) {
  const nums=raw.split(',').map(Number);
  if(nums.length!==4||nums.some(n=>!Number.isFinite(n)))throw new Error('Ogiltig kartyta');
  const [s,w,n,e]=nums;
  if(s<55.1||n>69.2||w<10.7||e>24.4||s>=n||w>=e||n-s>0.65||e-w>0.9)throw new Error('Zooma in för att visa alla mackar i området');
  // Cache-grid: avrundat område per användarförfrågan; klienten väntar tills kartan stillnat.
  const query=`[out:json][timeout:25];nwr["amenity"="fuel"](${s.toFixed(4)},${w.toFixed(4)},${n.toFixed(4)},${e.toFixed(4)});out center tags;`;
  return catalogFor('bbox:'+nums.map(n=>n.toFixed(2)).join(','),query);
}

const mimeTypes = {
  '.html': 'text/html; charset=utf-8', '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.webmanifest':'application/manifest+json; charset=utf-8',
  '.svg': 'image/svg+xml', '.png': 'image/png', '.webp': 'image/webp',
  '.ico': 'image/x-icon', '.txt': 'text/plain; charset=utf-8',
};
function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(JSON.stringify(body));
}

const placesCache = new Map();
let lastPlacesFetchAt = 0;

export async function handler(req, res) {
  let url;
  try { url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`); }
  catch { return json(res, 400, { error: 'Ogiltig URL' }); }
  if (req.method !== 'GET' && req.method !== 'HEAD') return json(res, 405, { error: 'Metoden stöds inte' });
  if(url.pathname === '/api/catalog') {
    const city=String(url.searchParams.get('city')||'').trim();
    const bbox=String(url.searchParams.get('bbox')||'').trim();
    if (!((city && city.length<=70 && /^[\p{L}\p{M} .'-]+$/u.test(city)) || (bbox && bbox.length<=120))) {
      return json(res,400,{error:'Ange ort eller kartområde'});
    }
    try {
      const data=city? await stationsInCity(city):await stationsInMapBox(bbox);
      return json(res,200,{source:'OpenStreetMap',city:city||null,center:data.center||null,stale:data.stale,stations:data.stations,
        note:'Registrerade mackar, inte prisuppgifter. OpenStreetMap kan sakna vissa stationer.'});
    } catch(e){return json(res,503,{error:e?.message||'Kunde inte hämta stationer från OpenStreetMap'});}
  }
  if (url.pathname === '/api/stations') {
    await getStations(url.searchParams.get('refresh') === '1');
    const age = state.fetchedAt ? Date.now() - Date.parse(state.fetchedAt) : Infinity;
    if (!state.fetchedAt || age > MAX_STALE_MS) {
      return json(res, 503, { error: 'Kunde inte hämta tillräckligt färska stationsuppgifter.', details: state.lastError, source: state.sourceUsed });
    }
    return json(res, 200, {
      source: state.sourceUsed, sourceUrl: state.sourceLink,
      fetchedAt: state.fetchedAt, stale: Boolean(state.lastError) || age >= FRESH_MS,
      caution: 'Användarrapporterade priser – inte verifierad realtid. Enskilda priser kan vara upp till tre dygn gamla enligt originalkällan. Kontrollera alltid priset vid pumpen.',
      stations: state.stations,
    });
  }
  if (url.pathname === '/api/places') {
    const q = String(url.searchParams.get('q') || '').trim();
    if (q.length < 2 || q.length > 65 || !/^[\p{L}\p{M} .'-]+$/u.test(q)) return json(res, 200, { cities: [] });
    const key = q.toLocaleLowerCase('sv-SE');
    const previous = placesCache.get(key);
    if (previous && Date.now() - previous.at < 15 * 60 * 1000) return json(res, 200, { cities: previous.cities });
    // Komoot Photon är en demonstrationstjänst: timeout, caching och en mild global rate limit.
    if (Date.now() - lastPlacesFetchAt < 1100) return json(res, 200, { cities: previous?.cities || [] });
    lastPlacesFetchAt = Date.now();
    const upstream = new URL('https://photon.komoot.io/api/');
    upstream.searchParams.set('q', q); upstream.searchParams.set('limit', '12'); upstream.searchParams.set('lang', 'sv');
    upstream.searchParams.set('lat','59.6'); upstream.searchParams.set('lon','15.3');
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 4000);
    try {
      const response = await fetch(upstream, {signal:controller.signal, headers:{Accept:'application/json'}});
      if (!response.ok) throw new Error('Otillgängligt ortsregister');
      const data = await response.json();
      const normalize = str => String(str||'').toLocaleLowerCase('sv-SE').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
      const seen = new Set(); const cities = [];
      for (const feature of (Array.isArray(data.features) ? data.features.slice(0,40) : [])) {
        const p = feature.properties || {};
        if (String(p.countrycode||'').toUpperCase() !== 'SE') continue;
        if (!['city','town','village','hamlet','municipality'].includes(String(p.osm_value||''))) continue;
        const name = String(p.name || '').trim().slice(0,65);
        if (!name || !normalize(name).startsWith(normalize(q)) || seen.has(normalize(name))) continue;
        seen.add(normalize(name)); cities.push(name);
      }
      if (placesCache.size > 180) placesCache.clear();
      placesCache.set(key,{ at: Date.now(), cities });
      return json(res, 200, { cities });
    } catch { return json(res, 200, { cities: previous?.cities || [] }); }
    finally { clearTimeout(timeout); }
  }
  if (url.pathname === '/api/diagnostik') {
    await getStations();
    return json(res, 200, { source: state.sourceUsed, fetchedAt: state.fetchedAt, count: state.stations.length, prices: state.stations.reduce((n,s)=>n+Object.keys(s.prices).length,0), error: state.lastError, sourceFormat: state.sourceFormat });
  }
  if (url.pathname === '/api/health') return json(res, 200, { ok: true, version:'5.0.0', sourceFetchedAt: state.fetchedAt, stationCount: state.stations.length });
  let requested;
  try { requested = decodeURIComponent(url.pathname); } catch { return json(res, 400, { error: 'Ogiltig sökväg' }); }
  if (requested.includes('\0')) return json(res, 400, { error: 'Ogiltig sökväg' });
  const filename = requested === '/' ? '/index.html' : requested;
  const file = STATIC_FILES.get(filename);
  if (!file) return json(res, 404, { error: 'Sidan hittades inte' });
  const mime = mimeTypes[path.extname(filename)] || 'application/octet-stream';
  res.writeHead(200, {
    'Content-Type': mime, 'Content-Length': file.length,
    'X-Content-Type-Options': 'nosniff',
    'Cache-Control': ['/index.html','/app.js','/style.css','/service-worker.js','/manifest.webmanifest'].includes(filename) ? 'no-store, max-age=0' : 'public, max-age=300',
  });
  if (req.method === 'HEAD') return res.end();
  return res.end(file);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const server = http.createServer((req, res) => { handler(req, res).catch(err => {
    console.error(err);
    if (!res.headersSent) json(res, 500, { error: 'Serverfel' }); else res.end();
  }); });
  server.listen(PORT, '0.0.0.0', () => console.log(`Tankkollen: http://localhost:${PORT}`));
}
